/**
 * NT Design System - Unified Bundle
 * 
 * Consolidated vanilla JavaScript components for Squiz Matrix deployment.
 * Components auto-initialize on DOMContentLoaded.
 * 
 * Generated: 2026-02-13T07:57:54.435Z
 */

// ============================================
// Header Component
// ============================================
/**
 * Vanilla JS Header Component
 * Lightweight implementation without React dependency for Squiz Matrix embedding
 */

import "./Header.css";

export interface HeaderConfig {
  title?: string;
  logoSrc?: string;
  logoAlt?: string;
  icon?: string;
  onMenuClick?: () => void;
}

export class HeaderComponent {
  private container: HTMLElement;
  private config: HeaderConfig;

  constructor(container: HTMLElement, config: HeaderConfig = {}) {
    this.container = container;
    this.config = {
      title: config.title || "Web Design System",
      logoSrc:
        config.logoSrc ||
        "https://nt.gov.au/_design/latest/images/ntg-primary-reverse.svg",
      logoAlt: config.logoAlt || "NT Government Logo",
      icon: config.icon || "fa-magnifying-glass",
      onMenuClick: config.onMenuClick,
    };

    this.render();
  }

  private render(): void {
    this.container.innerHTML = `
      <div class="nt-header">
        <div class="nt-header__inner">
          <div class="nt-header__left">
            <div class="nt-header__logo-section">
              <img src="${this.config.logoSrc}" alt="${this.config.logoAlt}" class="nt-header__logo" />
              <div class="nt-header__title">${this.config.title}</div>
            </div>
          </div>
          <div class="nt-header__right">
            <div class="nt-header__actions">
              <button class="nt-header__menu-button" aria-label="Menu">
                <div class="nt-header__icon-container">
                  <i class="fa-light ${this.config.icon}"></i>
                </div>
              </button>
            </div>
          </div>
        </div>
      </div>
    `;

    // Attach event listener if callback provided
    if (this.config.onMenuClick) {
      const menuButton = this.container.querySelector(
        ".nt-header__menu-button",
      );
      if (menuButton) {
        menuButton.addEventListener("click", this.config.onMenuClick);
      }
    }
  }

  public updateConfig(config: Partial<HeaderConfig>): void {
    this.config = { ...this.config, ...config };
    this.render();
  }

  public destroy(): void {
    this.container.innerHTML = "";
  }
}

// Auto-mount functionality for standalone use
if (typeof document !== "undefined") {
  const initHeader = () => {
    const container = document.getElementById("nt-header-root");

    if (container) {
      // Read configuration from data attributes
      const config: HeaderConfig = {
        title: container.getAttribute("data-title") || undefined,
        logoSrc: container.getAttribute("data-logo-src") || undefined,
        logoAlt: container.getAttribute("data-logo-alt") || undefined,
        icon: container.getAttribute("data-icon") || undefined,
      };

      new HeaderComponent(container, config);
    }
  };

  // Initialize on DOM ready
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initHeader);
  } else {
    initHeader();
  }
}

// Expose HeaderComponent globally to prevent variable name conflicts with minification
declare global {
  interface Window {
    NTGHeader: typeof HeaderComponent;
  }
}

if (typeof window !== "undefined") {
  window.NTGHeader = HeaderComponent;
}


// ============================================
// LeftNav Component
// ============================================
/**
 * Vanilla JS Left Navigation Component
 * Lightweight implementation without React dependency for Squiz Matrix embedding
 */

import "./LeftNav.css";

export interface LeftNavConfig {
  defaultExpanded?: string[]; // Array of section IDs to expand by default
  mobileBreakpoint?: number; // Mobile breakpoint in pixels
}

export class LeftNavComponent {
  private container: HTMLElement;
  private config: LeftNavConfig;
  private expandedSections: Set<string>;
  private isMobileOpen: boolean = false;
  private mobileToggle: HTMLButtonElement | null = null;
  private overlay: HTMLElement | null = null;
  private closeButton: HTMLButtonElement | null = null;
  private nav: HTMLElement | null = null;

  constructor(container: HTMLElement, config: LeftNavConfig = {}) {
    this.container = container;
    this.config = {
      defaultExpanded: config.defaultExpanded || [],
      mobileBreakpoint: config.mobileBreakpoint || 768,
    };
    this.expandedSections = new Set(this.config.defaultExpanded);

    this.render();
    this.attachEventListeners();
    this.expandActiveSection();
  }

  private render(): void {
    // Add mobile elements if not already present
    if (!this.container.querySelector(".nt-leftnav__mobile-toggle")) {
      const mobileToggle = document.createElement("button");
      mobileToggle.className = "nt-leftnav__mobile-toggle";
      mobileToggle.setAttribute("aria-label", "Open navigation menu");
      mobileToggle.setAttribute("aria-expanded", "false");
      mobileToggle.innerHTML =
        '<i class="fa-light fa-bars" aria-hidden="true"></i>';
      this.container.insertBefore(mobileToggle, this.container.firstChild);
    }

    if (!this.container.querySelector(".nt-leftnav__overlay")) {
      const overlay = document.createElement("div");
      overlay.className = "nt-leftnav__overlay";
      overlay.setAttribute("aria-hidden", "true");
      this.container.insertBefore(overlay, this.container.firstChild);
    }

    // Find or create nav element
    this.nav = this.container.querySelector("nav.nt-leftnav");
    if (this.nav && !this.nav.querySelector(".nt-leftnav__close")) {
      const closeButton = document.createElement("button");
      closeButton.className = "nt-leftnav__close";
      closeButton.setAttribute("aria-label", "Close navigation menu");
      closeButton.innerHTML =
        '<i class="fa-light fa-times" aria-hidden="true"></i>';
      this.nav.insertBefore(closeButton, this.nav.firstChild);
    }

    this.mobileToggle = this.container.querySelector(
      ".nt-leftnav__mobile-toggle",
    );
    this.overlay = this.container.querySelector(".nt-leftnav__overlay");
    this.closeButton = this.container.querySelector(".nt-leftnav__close");

    // Update submenu states based on expandedSections
    this.updateSubmenuStates();
  }

  private attachEventListeners(): void {
    // Toggle buttons for expandable sections
    const toggleButtons = this.container.querySelectorAll(
      ".nt-leftnav__toggle",
    );
    toggleButtons.forEach((button) => {
      button.addEventListener("click", this.handleToggleClick.bind(this));
      button.addEventListener("keydown", this.handleToggleKeyDown.bind(this));
    });

    // Mobile toggle button
    if (this.mobileToggle) {
      this.mobileToggle.addEventListener(
        "click",
        this.openMobileDrawer.bind(this),
      );
    }

    // Close button
    if (this.closeButton) {
      this.closeButton.addEventListener(
        "click",
        this.closeMobileDrawer.bind(this),
      );
    }

    // Overlay click
    if (this.overlay) {
      this.overlay.addEventListener("click", this.closeMobileDrawer.bind(this));
    }

    // Escape key to close drawer
    document.addEventListener("keydown", this.handleEscapeKey.bind(this));
  }

  private handleToggleClick(event: Event): void {
    const button = event.currentTarget as HTMLButtonElement;
    const submenuId = button.getAttribute("aria-controls");
    if (!submenuId) return;

    const submenu = document.getElementById(submenuId);
    if (!submenu) return;

    // Extract section ID from submenu ID (format: submenu-{sectionId})
    const sectionId = submenuId.replace("submenu-", "");
    this.toggleSection(sectionId);
  }

  private handleToggleKeyDown(event: Event): void {
    const keyboardEvent = event as KeyboardEvent;
    if (keyboardEvent.key === "Enter" || keyboardEvent.key === " ") {
      keyboardEvent.preventDefault();
      this.handleToggleClick(event);
    }
  }

  private handleEscapeKey(event: Event): void {
    const keyboardEvent = event as KeyboardEvent;
    if (keyboardEvent.key === "Escape" && this.isMobileOpen) {
      this.closeMobileDrawer();
    }
  }

  public toggleSection(sectionId: string): void {
    if (this.expandedSections.has(sectionId)) {
      this.expandedSections.delete(sectionId);
    } else {
      this.expandedSections.add(sectionId);
    }
    this.updateSubmenuStates();
  }

  private updateSubmenuStates(): void {
    const toggleButtons = this.container.querySelectorAll(
      ".nt-leftnav__toggle",
    );

    toggleButtons.forEach((button) => {
      const submenuId = button.getAttribute("aria-controls");
      if (!submenuId) return;

      const submenu = document.getElementById(submenuId);
      if (!submenu) return;

      const sectionId = submenuId.replace("submenu-", "");
      const isExpanded = this.expandedSections.has(sectionId);

      button.setAttribute("aria-expanded", String(isExpanded));
      submenu.setAttribute("aria-hidden", String(!isExpanded));

      if (isExpanded) {
        submenu.classList.add("nt-leftnav__submenu--expanded");
      } else {
        submenu.classList.remove("nt-leftnav__submenu--expanded");
      }
    });
  }

  private expandActiveSection(): void {
    // Find all active links (check both aria-current and active class from Squiz Matrix)
    const activeLinks = this.container.querySelectorAll(
      '[aria-current="page"], .nt-leftnav__subitem.active .nt-leftnav__link, .nt-leftnav__item.active > .nt-leftnav__link',
    );

    activeLinks.forEach((link) => {
      // Find parent submenu
      const submenu = link.closest(".nt-leftnav__submenu");
      if (submenu) {
        const submenuId = submenu.id;
        const sectionId = submenuId.replace("submenu-", "");
        this.expandedSections.add(sectionId);
      }
    });

    this.updateSubmenuStates();
  }

  private openMobileDrawer(): void {
    this.isMobileOpen = true;

    if (this.nav) {
      this.nav.classList.add("nt-leftnav--open");
    }
    if (this.overlay) {
      this.overlay.classList.add("nt-leftnav__overlay--visible");
    }
    if (this.mobileToggle) {
      this.mobileToggle.setAttribute("aria-expanded", "true");
    }

    // Lock body scroll
    document.body.style.overflow = "hidden";
  }

  private closeMobileDrawer(): void {
    this.isMobileOpen = false;

    if (this.nav) {
      this.nav.classList.remove("nt-leftnav--open");
    }
    if (this.overlay) {
      this.overlay.classList.remove("nt-leftnav__overlay--visible");
    }
    if (this.mobileToggle) {
      this.mobileToggle.setAttribute("aria-expanded", "false");
    }

    // Unlock body scroll
    document.body.style.overflow = "";
  }

  public updateConfig(config: Partial<LeftNavConfig>): void {
    this.config = { ...this.config, ...config };
    if (config.defaultExpanded) {
      this.expandedSections = new Set(config.defaultExpanded);
      this.updateSubmenuStates();
    }
  }

  public destroy(): void {
    // Remove event listeners
    const toggleButtons = this.container.querySelectorAll(
      ".nt-leftnav__toggle",
    );
    toggleButtons.forEach((button) => {
      button.removeEventListener("click", this.handleToggleClick.bind(this));
      button.removeEventListener(
        "keydown",
        this.handleToggleKeyDown.bind(this),
      );
    });

    if (this.mobileToggle) {
      this.mobileToggle.removeEventListener(
        "click",
        this.openMobileDrawer.bind(this),
      );
    }
    if (this.closeButton) {
      this.closeButton.removeEventListener(
        "click",
        this.closeMobileDrawer.bind(this),
      );
    }
    if (this.overlay) {
      this.overlay.removeEventListener(
        "click",
        this.closeMobileDrawer.bind(this),
      );
    }

    document.removeEventListener("keydown", this.handleEscapeKey.bind(this));

    // Restore body scroll
    document.body.style.overflow = "";

    // Clear container
    this.container.innerHTML = "";
  }
}

// Auto-mount functionality for standalone use
if (typeof document !== "undefined") {
  const initLeftNav = () => {
    const container = document.getElementById("nt-leftnav-root");

    if (container) {
      // Read configuration from data attributes
      const defaultExpandedAttr = container.getAttribute(
        "data-default-expanded",
      );
      const config: LeftNavConfig = {
        defaultExpanded: defaultExpandedAttr
          ? defaultExpandedAttr.split(",")
          : [],
        mobileBreakpoint: parseInt(
          container.getAttribute("data-mobile-breakpoint") || "768",
          10,
        ),
      };

      new LeftNavComponent(container, config);
    }
  };

  // Initialize on DOM ready
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initLeftNav);
  } else {
    initLeftNav();
  }
}

// Expose LeftNavComponent globally to prevent variable name conflicts with minification
declare global {
  interface Window {
    NTGLeftNav: typeof LeftNavComponent;
  }
}

if (typeof window !== "undefined") {
  window.NTGLeftNav = LeftNavComponent;
}


// ============================================
// ThemeSwitcher Component
// ============================================
/**
 * ThemeSwitcher Vanilla JS - Client-Side Hydration
 *
 * Multi-URL theme switcher with tab navigation supporting up to 3 themes.
 * Reads minimal server-rendered container and renders full HTML with interactivity.
 * Loaded globally and auto-detects all [data-hydration-component="theme-switcher"] elements.
 */

import "./ThemeSwitcher.css";

export interface ThemeItem {
  name: string;
  url: string;
}

export interface ThemeSwitcherProps {
  themes: ThemeItem[];
  height?: string;
  defaultTheme?: string;
}

export class ThemeSwitcherClient {
  private container: HTMLElement;
  private props: ThemeSwitcherProps;
  private activeThemeIndex: number = 0;
  private iframes: Map<number, HTMLIFrameElement> = new Map();

  constructor(container: HTMLElement) {
    this.container = container;

    console.log("[ThemeSwitcher] Initializing for container:", container);
    console.log(
      "[ThemeSwitcher] Raw data-hydration-props:",
      container.getAttribute("data-hydration-props"),
    );
    console.log(
      "[ThemeSwitcher] Dataset hydrationProps:",
      container.dataset.hydrationProps,
    );

    // Parse props from data-hydration-props
    try {
      this.props = JSON.parse(container.dataset.hydrationProps || "{}");
      console.log("[ThemeSwitcher] Parsed props successfully:", this.props);
    } catch (error) {
      console.error("[ThemeSwitcher] Failed to parse hydration props:", error);
      console.error(
        "[ThemeSwitcher] Raw value:",
        container.dataset.hydrationProps,
      );
      this.renderError(
        `Failed to parse props: ${error instanceof Error ? error.message : String(error)}`,
      );
      this.props = {
        themes: [],
      };
      return;
    }

    // Validate props
    if (!this.props.themes || this.props.themes.length === 0) {
      console.error("[ThemeSwitcher] No themes provided in props");
      this.renderError("No themes provided");
      return;
    }

    if (this.props.themes.length > 3) {
      console.error(
        "[ThemeSwitcher] Too many themes:",
        this.props.themes.length,
      );
      this.renderError("Maximum 3 themes allowed");
      return;
    }

    // Validate each theme
    for (const theme of this.props.themes) {
      if (!theme.name || !theme.url) {
        console.error("[ThemeSwitcher] Invalid theme object:", theme);
        this.renderError("Each theme must have a name and url");
        return;
      }
    }

    console.log(
      "[ThemeSwitcher] Validation passed, rendering",
      this.props.themes.length,
      "theme(s)",
    );

    // Determine active theme
    this.activeThemeIndex = this.getInitialThemeIndex();

    // Render the HTML
    this.render();

    // Setup event listeners
    this.setupEventListeners();

    console.log("[ThemeSwitcher] Initialization complete");
  }

  private getInitialThemeIndex(): number {
    const { themes, defaultTheme } = this.props;

    // If defaultTheme is specified, find its index
    if (defaultTheme) {
      const index = themes.findIndex((t) => t.name === defaultTheme);
      if (index !== -1) {
        return index;
      }
    }

    // Default to first theme
    return 0;
  }

  private renderError(message: string): void {
    this.container.innerHTML = `
      <div class="nt-theme-switcher-error" style="padding: 2rem; background: #fee; border: 2px solid #c33; color: #c33; border-radius: 4px;">
        <strong>Theme Switcher Error:</strong> ${this.escapeHtml(message)}
      </div>
    `;
  }

  private render(): void {
    const { themes, height = "600px" } = this.props;

    // If only one theme, don't show tabs - just the iframe
    if (themes.length === 1) {
      this.container.innerHTML = `
        <div class="nt-theme-switcher__content">
          <iframe
            src="${this.escapeHtml(themes[0].url)}"
            class="nt-theme-switcher__iframe"
            style="height: ${this.escapeHtml(height)};"
            title="${this.escapeHtml(themes[0].name)}"
            frameborder="0"
            data-theme-index="0"
          ></iframe>
        </div>
      `;
      return;
    }

    // Multiple themes - show tabs
    const tabsHtml = themes
      .map((theme, index) => {
        const isActive = index === this.activeThemeIndex;
        return `
        <button
          class="nt-theme-switcher__tab ${isActive ? "nt-theme-switcher__tab--active" : ""}"
          data-theme-index="${index}"
          aria-selected="${isActive}"
          role="tab"
        >
          ${this.escapeHtml(theme.name)}
        </button>
      `;
      })
      .join("");

    const iframesHtml = themes
      .map((theme, index) => {
        const isActive = index === this.activeThemeIndex;
        return `
        <iframe
          src="${this.escapeHtml(theme.url)}"
          class="nt-theme-switcher__iframe"
          style="height: ${this.escapeHtml(height)}; display: ${isActive ? "block" : "none"};"
          title="${this.escapeHtml(theme.name)}"
          frameborder="0"
          data-theme-index="${index}"
        ></iframe>
      `;
      })
      .join("");

    this.container.innerHTML = `
      <div class="nt-theme-switcher__tabs" role="tablist">
        ${tabsHtml}
      </div>
      <div class="nt-theme-switcher__content">
        ${iframesHtml}
      </div>
    `;

    // Store iframe references
    this.container
      .querySelectorAll(".nt-theme-switcher__iframe")
      .forEach((iframe) => {
        const index = parseInt(
          (iframe as HTMLElement).dataset.themeIndex || "0",
          10,
        );
        this.iframes.set(index, iframe as HTMLIFrameElement);
      });
  }

  private escapeHtml(str: string): string {
    return (str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  private setupEventListeners(): void {
    // Get all tab buttons
    const tabs = this.container.querySelectorAll(".nt-theme-switcher__tab");

    tabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        const index = parseInt(
          (tab as HTMLElement).dataset.themeIndex || "0",
          10,
        );
        this.switchTheme(index);
      });
    });
  }

  private switchTheme(newIndex: number): void {
    if (newIndex === this.activeThemeIndex) return;

    const oldIndex = this.activeThemeIndex;
    this.activeThemeIndex = newIndex;

    // Update tab states
    const tabs = this.container.querySelectorAll(".nt-theme-switcher__tab");
    tabs.forEach((tab, index) => {
      if (index === newIndex) {
        tab.classList.add("nt-theme-switcher__tab--active");
        tab.setAttribute("aria-selected", "true");
      } else {
        tab.classList.remove("nt-theme-switcher__tab--active");
        tab.setAttribute("aria-selected", "false");
      }
    });

    // Show/hide iframes
    const oldIframe = this.iframes.get(oldIndex);
    const newIframe = this.iframes.get(newIndex);

    if (oldIframe) {
      oldIframe.style.display = "none";
    }

    if (newIframe) {
      newIframe.style.display = "block";
    }
  }
}

// Auto-initialize all ThemeSwitcher instances on page load
(function () {
  if (typeof document !== "undefined") {
    const initThemeSwitchers = () => {
      console.log(
        "[ThemeSwitcher] Auto-initialization starting, readyState:",
        document.readyState,
      );
      const containers = document.querySelectorAll(
        '[data-hydration-component="theme-switcher"]',
      );
      console.log(
        "[ThemeSwitcher] Found",
        containers.length,
        "container(s) to hydrate",
      );

      if (containers.length === 0) {
        console.warn(
          '[ThemeSwitcher] No elements found with data-hydration-component="theme-switcher"',
        );
      }

      containers.forEach((container, index) => {
        console.log(
          `[ThemeSwitcher] Hydrating container ${index + 1}/${containers.length}`,
        );
        try {
          new ThemeSwitcherClient(container as HTMLElement);
        } catch (error) {
          console.error(
            `[ThemeSwitcher] Failed to initialize container ${index + 1}:`,
            error,
          );
        }
      });

      console.log("[ThemeSwitcher] Auto-initialization complete");
    };

    if (document.readyState === "loading") {
      console.log(
        "[ThemeSwitcher] Document still loading, waiting for DOMContentLoaded",
      );
      document.addEventListener("DOMContentLoaded", initThemeSwitchers);
    } else {
      console.log(
        "[ThemeSwitcher] Document already loaded, initializing immediately",
      );
      initThemeSwitchers();
    }
  }
})();

export default ThemeSwitcherClient;


// ============================================
// ComponentViewer Component
// ============================================
/**
 * ComponentViewer Vanilla JS - Client-Side Hydration
 *
 * Reads minimal server-rendered container and renders full HTML with interactivity.
 * Loaded globally and auto-detects all [data-hydration-component="component-viewer"] elements.
 */

// Type definitions for external libraries
declare global {
  interface Window {
    Prism: any;
    prettier: any;
    prettierPlugins: any;
  }
}

export interface ComponentViewerProps {
  storybookUrl: string;
  codeExample?: string;
  height?: string;
  initialZoom?: number;
  showCodeByDefault?: boolean;
  enableCopy?: boolean;
  enableZoom?: boolean;
}

export class ComponentViewerClient {
  private container: HTMLElement;
  private props: ComponentViewerProps;
  private iframe: HTMLIFrameElement | null = null;
  private zoomContainer: HTMLElement | null = null;
  private codePanel: HTMLElement | null = null;
  private codeDisplay: HTMLElement | null = null;
  private currentZoom: number;
  private isCodeVisible: boolean;
  private extractedCode: string = "";

  constructor(container: HTMLElement) {
    this.container = container;

    // Parse props from data-hydration-props
    try {
      this.props = JSON.parse(container.dataset.hydrationProps || "{}");
    } catch (error) {
      console.error("Failed to parse hydration props:", error);
      this.props = {
        storybookUrl: "",
      };
    }

    // Initialize state
    this.currentZoom = this.props.initialZoom || 1;
    this.isCodeVisible = this.props.showCodeByDefault || false;

    // Render the HTML
    this.render();

    // Get rendered elements
    this.iframe = container.querySelector("[data-iframe]") as HTMLIFrameElement;
    this.zoomContainer = container.querySelector(
      "[data-zoom-container]",
    ) as HTMLElement;
    this.codePanel = container.querySelector(
      "[data-code-panel]",
    ) as HTMLElement;
    this.codeDisplay = container.querySelector(
      "[data-code-display]",
    ) as HTMLElement;

    // Setup event listeners
    this.setupEventListeners();

    // Wait for iframe to load, then extract code
    if (this.iframe) {
      this.iframe.addEventListener("load", () => {
        setTimeout(() => this.extractIframeContent(), 1000);
      });
    }

    // Apply initial zoom
    if (this.currentZoom !== 1) {
      this.applyZoom();
    }
  }

  private render(): void {
    const {
      storybookUrl,
      height = "200px",
      showCodeByDefault = false,
      enableCopy = true,
      enableZoom = true,
    } = this.props;

    const zoomControls = enableZoom
      ? `
            <div class="component-viewer__zoom-controls">
              <button 
                class="component-viewer__control-btn" 
                data-action="zoom-in"
                aria-label="Zoom in"
                title="Zoom in"
              >
                <i class="fa-light fa-magnifying-glass-plus" aria-hidden="true"></i>
                <span class="component-viewer__control-label">Zoom in</span>
              </button>
              <button 
                class="component-viewer__control-btn" 
                data-action="zoom-out"
                aria-label="Zoom out"
                title="Zoom out"
              >
                <i class="fa-light fa-magnifying-glass-minus" aria-hidden="true"></i>
                <span class="component-viewer__control-label">Zoom out</span>
              </button>
              <button 
                class="component-viewer__control-btn" 
                data-action="zoom-reset"
                aria-label="Reset zoom"
                title="Reset zoom"
              >
                <i class="fa-light fa-arrows-rotate" aria-hidden="true"></i>
                <span class="component-viewer__control-label">Reset zoom</span>
              </button>
            </div>`
      : "";

    const copyButton = enableCopy
      ? `
        <button 
          class="component-viewer__button" 
          data-action="copy"
          aria-label="Copy code to clipboard"
        >
          <i class="fa-light fa-copy" aria-hidden="true"></i>
          <span data-copy-text>Copy</span>
        </button>`
      : "";

    this.container.innerHTML = `
      <!-- Preview Section -->
      <div class="component-viewer__preview" style="height: ${this.escapeHtml(height)}">
        <div class="component-viewer__iframe-wrapper">
          
          <!-- Toolbar -->
          <div class="component-viewer__toolbar">
            ${zoomControls}
            <button 
              class="component-viewer__control-btn" 
              data-action="open-new-tab"
              aria-label="Open canvas in new tab"
              title="Open canvas in new tab"
            >
              <i class="fa-light fa-arrow-up-right-from-square" aria-hidden="true"></i>
              <span class="component-viewer__control-label">Open canvas in new tab</span>
            </button>
          </div>

          <!-- Iframe Content -->
          <div class="component-viewer__iframe-content" data-zoom-container>
            <iframe
              src="${this.escapeHtml(storybookUrl)}"
              class="component-viewer__iframe"
              title="Component Preview"
              frameborder="0"
              sandbox="allow-scripts allow-same-origin"
              data-iframe
            ></iframe>
          </div>
        </div>
      </div>

      <!-- Code Display Section -->
      <div class="component-viewer__code ${showCodeByDefault ? "component-viewer__code--visible" : ""}" data-code-panel>
        <pre class="component-viewer__code-content"><code class="language-html" data-code-display></code></pre>
      </div>

      <!-- Action Buttons -->
      <div class="component-viewer__actions">
        ${copyButton}
        <button 
          class="component-viewer__button" 
          data-action="toggle-code"
          aria-label="${showCodeByDefault ? "Hide code" : "See code"}"
        >
          <i class="fa-light fa-code" aria-hidden="true"></i>
          <span data-code-toggle-text>${showCodeByDefault ? "Hide code" : "See code"}</span>
        </button>
      </div>
    `;
  }

  private escapeHtml(str: string): string {
    return (str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  private setupEventListeners(): void {
    // Get all action buttons
    const buttons = this.container.querySelectorAll("[data-action]");

    buttons.forEach((button) => {
      const action = (button as HTMLElement).dataset.action;

      switch (action) {
        case "zoom-in":
          button.addEventListener("click", () => this.handleZoomIn());
          break;
        case "zoom-out":
          button.addEventListener("click", () => this.handleZoomOut());
          break;
        case "zoom-reset":
          button.addEventListener("click", () => this.handleZoomReset());
          break;
        case "open-new-tab":
          button.addEventListener("click", () => this.handleOpenNewTab());
          break;
        case "copy":
          button.addEventListener("click", () => this.handleCopy());
          break;
        case "toggle-code":
          button.addEventListener("click", () => this.handleToggleCode());
          break;
      }
    });
  }

  private handleZoomIn(): void {
    this.currentZoom = Math.min(this.currentZoom + 0.1, 2);
    this.applyZoom();
  }

  private handleZoomOut(): void {
    this.currentZoom = Math.max(this.currentZoom - 0.1, 0.5);
    this.applyZoom();
  }

  private handleZoomReset(): void {
    this.currentZoom = 1;
    this.applyZoom();
  }

  private applyZoom(): void {
    if (this.zoomContainer) {
      this.zoomContainer.style.transform = `scale(${this.currentZoom})`;
    }
  }

  private handleOpenNewTab(): void {
    if (this.iframe) {
      const src = this.iframe.getAttribute("src");
      if (src) {
        window.open(src, "_blank");
      }
    }
  }

  private async handleCopy(): Promise<void> {
    const copyTextEl = this.container.querySelector("[data-copy-text]");

    try {
      await navigator.clipboard.writeText(
        this.extractedCode || this.props.codeExample || "",
      );

      if (copyTextEl) {
        const originalText = copyTextEl.textContent;
        copyTextEl.textContent = "Copied!";
        setTimeout(() => {
          copyTextEl.textContent = originalText;
        }, 2000);
      }
    } catch (err) {
      console.error("Copy failed:", err);
    }
  }

  private handleToggleCode(): void {
    this.isCodeVisible = !this.isCodeVisible;

    if (this.codePanel) {
      if (this.isCodeVisible) {
        this.codePanel.classList.add("component-viewer__code--visible");
        if (!this.extractedCode) {
          // No extracted code yet — extract (formatCode will animate when done)
          this.extractIframeContent();
        } else if (this.codeDisplay) {
          // We already have formatted code — animate typing now
          this.animateTyping(this.extractedCode);
        }
      } else {
        this.codePanel.classList.remove("component-viewer__code--visible");
      }
    }

    // Update button text
    const toggleText = this.container.querySelector("[data-code-toggle-text]");
    if (toggleText) {
      toggleText.textContent = this.isCodeVisible ? "Hide code" : "See code";
    }

    // Update aria-label
    const toggleButton = this.container.querySelector(
      '[data-action="toggle-code"]',
    );
    if (toggleButton) {
      toggleButton.setAttribute(
        "aria-label",
        this.isCodeVisible ? "Hide code" : "See code",
      );
    }
  }

  private extractIframeContent(): void {
    try {
      if (!this.iframe) {
        this.formatCode(this.props.codeExample || "<!-- Iframe not found -->");
        return;
      }

      const iframeDoc =
        this.iframe.contentDocument || this.iframe.contentWindow?.document;

      if (!iframeDoc) {
        console.warn("Cannot access iframe document");
        this.formatCode(
          this.props.codeExample || "<!-- Unable to access iframe -->",
        );
        return;
      }

      // Try multiple selectors
      const selectors = [
        "#storybook-root",
        "[data-story-block]",
        ".sb-story",
        "#storybook-docs",
        '[id*="story"]',
        "#root",
        "body",
      ];

      let root = null;
      for (const selector of selectors) {
        const element = iframeDoc.querySelector(selector);
        if (element && element.innerHTML.trim()) {
          root = element;
          break;
        }
      }

      if (root && root.innerHTML.trim()) {
        let extractedHTML = root.innerHTML.trim();

        // Strip outer container if it's a single div
        const tempDiv = document.createElement("div");
        tempDiv.innerHTML = extractedHTML;

        if (
          tempDiv.children.length === 1 &&
          tempDiv.children[0].tagName.toLowerCase() === "div"
        ) {
          extractedHTML = tempDiv.children[0].innerHTML.trim();
        }

        this.formatCode(extractedHTML);
      } else {
        this.formatCode(this.props.codeExample || "");
      }
    } catch (error) {
      console.error("Error extracting iframe content:", error);
      this.formatCode(
        this.props.codeExample || "<!-- Error extracting content -->",
      );
    }
  }

  /**
   * Remove common leading indentation from code
   * Fixes issue where first line has invisible indent from extracted HTML
   */
  private dedentCode(code: string): string {
    if (!code || !code.trim()) return code;

    const lines = code.split("\n");

    // Find minimum indentation (ignoring empty lines)
    let minIndent = Infinity;
    for (const line of lines) {
      if (line.trim().length === 0) continue; // Skip empty lines

      const leadingSpaces = line.match(/^[ \t]*/)?.[0].length || 0;
      if (leadingSpaces < minIndent) {
        minIndent = leadingSpaces;
      }
    }

    // If no indentation found or all lines are empty, return original
    if (minIndent === 0 || minIndent === Infinity) {
      return code.trim();
    }

    // Remove the minimum indentation from all lines
    const dedented = lines
      .map((line) => {
        if (line.trim().length === 0) return ""; // Empty lines become truly empty
        return line.slice(minIndent);
      })
      .join("\n");

    return dedented.trim();
  }

  private async formatCode(code: string): Promise<void> {
    // Remove common leading indentation from all lines
    const dedentedCode = this.dedentCode(code);
    this.extractedCode = dedentedCode;

    try {
      // Check if Prettier is available globally
      if (window.prettier && window.prettierPlugins) {
        const formatted = await window.prettier.format(dedentedCode, {
          parser: "html",
          plugins: window.prettierPlugins.html
            ? [window.prettierPlugins.html]
            : [],
          printWidth: 80,
          tabWidth: 2,
          useTabs: false,
          htmlWhitespaceSensitivity: "css",
        });

        this.extractedCode = formatted;
      } else {
        // Fallback without Prettier
        this.extractedCode = dedentedCode;
      }
    } catch (error) {
      console.error("Failed to format code:", error);
      this.extractedCode = dedentedCode;
    }

    // Only display (with typing effect) when the code panel is visible
    if (this.isCodeVisible) {
      this.animateTyping(this.extractedCode || "");
    } else if (this.codeDisplay) {
      // keep code panel empty until user opens it
      this.codeDisplay.textContent = "";
    }
  }

  private animateTyping(code: string, avgDelay = 12): void {
    if (!this.codeDisplay) return;

    // Clear existing content and add typing cursor class
    this.codeDisplay.textContent = "";
    this.codeDisplay.classList.add("typing-cursor");

    let i = 0;
    const len = code.length;

    const tick = () => {
      // Append next character
      this.codeDisplay!.textContent += code.charAt(i);
      i += 1;

      if (i < len) {
        // Randomize delay slightly to feel human/agent-like
        const jitter = Math.floor(Math.random() * 20) - 10;
        setTimeout(tick, Math.max(4, avgDelay + jitter));
      } else {
        // Finished typing: remove cursor and apply Prism highlighting
        setTimeout(() => {
          this.codeDisplay!.classList.remove("typing-cursor");
          if (window.Prism) {
            window.Prism.highlightElement(this.codeDisplay!);
          }
        }, 120);
      }
    };

    // Start
    if (len === 0) {
      // Nothing to type — immediately remove cursor and clear
      this.codeDisplay.classList.remove("typing-cursor");
      this.codeDisplay.textContent = "";
      return;
    }

    // Kick off the first tick
    setTimeout(tick, avgDelay);
  }
}

// Auto-initialize all ComponentViewer instances on page load
(function () {
  if (typeof document !== "undefined") {
    const initComponentViewers = () => {
      const containers = document.querySelectorAll(
        '[data-hydration-component="component-viewer"]',
      );
      containers.forEach((container) => {
        new ComponentViewerClient(container as HTMLElement);
      });
    };

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", initComponentViewers);
    } else {
      initComponentViewers();
    }
  }
})();

export default ComponentViewerClient;


